  "표8_상담적용": [
    {"상황": "오랜 미움으로 인해 삶의 방향과 목적을 잃어버린 성도", "성경원리": "미움은 영적 눈을 멀게 하여 갈 곳을 알지 못하게 만든다. 미움이 해소되지 않으면 삶 전체가 어둠에 지배된다", "실제적용": "미움의 뿌리를 함께 탐색하라. 용서가 즉각적으로 되지 않더라도 용서의 의지를 갖도록 도우라. 미움에서 벗어나는 것이 영적 시력 회복의 첫 단계이다"},
    {"상황": "미움의 감정을 통제할 수 없어 괴로운 성도", "성경원리": "어둠이 능동적으로 눈을 멀게 한다는 것은 미움이 자기 증식하는 힘이 있음을 의미한다. 인간의 힘만으로는 미움을 이기기 어렵다. 하나님의 사랑의 능력이 필요하다", "실제적용": "자력으로 미움을 해결하려는 시도에서 벗어나 하나님의 도우심을 구하도록 안내하라. 기도와 말씀 묵상을 통해 하나님의 사랑을 경험하는 것이 미움을 이기는 길이다"}
  ],
