    {"대지": "서론", "내용": "요한은 마지막 때라는 긴급한 선언으로 새로운 주제를 연다. 적그리스도의 출현이 마지막 때의 증거이다. 이 경고는 요한의 시대뿐 아니라 오늘의 교회에도 해당된다", "예화_적용": "화재 경보가 울리면 즉시 행동해야 한다. 마지막 때의 경보가 울리고 있다"},
    {"대지": "1대지: 마지막 때 (시대 인식)", "내용": "마지막 때는 그리스도의 첫 오심과 함께 시작되었다. 우리는 이미 마지막 시대에 살고 있다. 이 인식이 영적 긴장감을 유지하게 한다", "예화_적용": "마라톤의 마지막 구간은 가장 힘들지만 가장 중요하다. 마지막 때를 사는 성도에게도 깨어 있음이 가장 중요하다"},
    {"대지": "2대지: 많은 적그리스도 (경고)", "내용": "적그리스도는 한 명이 아니라 많다. 그리스도를 부인하는 모든 세력이 적그리스도이다. 교회 안팎에서 이런 세력이 활동하고 있다", "예화_적용": "바이러스가 변이를 거듭하듯 적그리스도의 세력도 다양한 형태로 나타난다. 분별력이 있어야 대처할 수 있다"},
    {"대지": "3대지: 분별의 지혜 (대응)", "내용": "마지막 때를 아는 것은 두려움이 아니라 분별의 지혜를 위한 것이다. 적그리스도를 분별하고 진리 안에 굳게 서는 것이 마지막 때의 성도의 자세이다", "예화_적용": "위조지폐를 알아보려면 진짜 지폐를 잘 알아야 한다. 적그리스도를 분별하려면 참 그리스도를 잘 알아야 한다"},
    {"대지": "결론", "내용": "우리는 마지막 때에 살고 있다. 많은 적그리스도가 활동하고 있다. 그러나 두려워하지 말라. 진리 안에 굳게 서서 그리스도를 붙잡으면 이길 수 있다", "예화_적용": "어두운 밤이 가장 깊어질 때 새벽이 가장 가까이 있다. 마지막 때가 깊어질수록 그리스도의 재림이 가까워진다"}
