    {"구절": "벧후 1:12", "연결점": "이러므로 너희가 이것을 알고 이미 있는 진리에 섰으나 내가 항상 너희에게 생각나게 하려 하노라", "구분": "신약"},
    {"구절": "시 119:160", "연결점": "주의 말씀의 강령은 진리이오니 주의 의로운 규례는 다 영원하니이다", "구분": "구약"},
    {"구절": "잠 23:23", "연결점": "진리를 사고서 팔지 말며 지혜와 훈계와 명철도 그리하라", "구분": "구약"}
