    {"항목": "서신의 목적 선언", "내용": "요한은 자신의 편지 목적을 분명히 밝힌다. 미혹에 대한 경고이다. 이것은 교리적 논쟁이 아니라 목회적 돌봄이다. 양을 늑대로부터 보호하려는 목자의 마음이다", "목회적활용": "교리 교육의 목적이 논쟁이 아니라 보호임을 기억하라. 성도들을 미혹에서 지키는 것이 목회자의 핵심 사명이다"}
