    {"상황": "도덕주의에 빠져 은혜를 잃어버린 성도", "성경원리": "정결의 동기는 율법이 아니라 소망이다. 그리스도와 같아질 소망이 정결의 동력이지 두려움이나 의무감이 아니다", "실제적용": "정결의 동기를 점검하게 하라. 두려움이나 의무감에서 오는 정결은 오래가지 못한다. 소망에서 오는 기쁜 정결을 경험하도록 도우라"}
