    {"원어": "ποιῶν (포이온)", "의미_문법": "짓는, 행하는 - 동사 현재 능동태 분사 남성 단수 주격. 계속적으로 죄를 행함", "설교포인트": "현재 분사는 습관적으로 죄를 짓는 생활 방식을 가리킨다. 한 번의 실수가 아니라 죄를 삶의 패턴으로 삼는 것이 문제이다"}
