    {"항목": "영지주의의 죄에 대한 무관심", "내용": "일부 영지주의자들은 영적 지식을 가진 자는 도덕적 행위와 무관하게 구원받았다고 주장했다. 요한은 이 가르침을 정면으로 반박하며 죄는 불법이라고 선언한다", "목회적활용": "은혜를 빌미로 죄에 무관심한 태도를 경계하라. 구원받은 자는 죄에 대해 더욱 민감해야 한다"}
