    {"교리": "죄의 습관성과 생활 패턴", "설명": "현재 분사의 사용은 일회적 실수가 아니라 죄를 습관적으로 짓는 생활 패턴을 의미한다. 요한이 경고하는 것은 죄를 삶의 방식으로 삼는 것이다", "관련구절": "롬 6:1-2, 히 10:26-27, 벧후 2:14"}
