    {"구분": "이스라엘의 금송아지 반역", "내용": "이스라엘은 시내산에서 율법을 받는 동안 금송아지를 만들어 경배하였다(출 32장). 이것은 하나님의 법을 받는 바로 그 순간에 불법을 행한 극단적 반역이었다", "그리스도연결": "이스라엘의 반역은 인간의 불법의 깊이를 보여준다. 그리스도만이 이 불법의 문제를 해결하시고 새 언약으로 하나님의 법을 마음에 기록하셨다"}
