    {"대지": "서론", "내용": "요한은 소망과 정결을 말한 후 이제 죄의 본질을 규정한다. 죄를 바로 알아야 죄에서 벗어날 수 있기 때문이다. 요한은 죄를 불법이라고 명확히 정의한다", "예화_적용": "의사가 병을 정확히 진단해야 치료할 수 있듯이 죄의 본질을 정확히 알아야 죄에서 벗어날 수 있다"},
    {"대지": "1대지: 죄를 짓는 자 (죄의 주체)", "내용": "현재 분사는 죄를 습관적으로 짓는 자를 가리킨다. 한 번의 실수가 아니라 죄를 삶의 패턴으로 삼는 자이다. 이것은 하나님의 자녀의 삶과 대조된다", "예화_적용": "한 번 넘어지는 것과 넘어져 있는 것은 다르다. 요한이 경고하는 것은 넘어진 채 일어나지 않는 삶이다"},
    {"대지": "2대지: 불법을 행함 (죄의 본질)", "내용": "불법은 하나님의 법에 대한 반역이다. 죄는 도덕적 실수가 아니라 하나님의 주권을 거부하는 반역 행위이다. 이 심각성을 인식해야 한다", "예화_적용": "국가의 법을 어기는 것은 국가의 권위에 도전하는 것이다. 하나님의 법을 어기는 것은 하나님의 통치를 거부하는 것이다"},
    {"대지": "3대지: 죄는 불법이라 (죄의 정의)", "내용": "요한은 죄와 불법을 동일시한다. 모든 죄는 하나님의 법에 대한 위반이다. 아무리 작아 보이는 죄도 하나님의 뜻을 벗어나는 불법 행위이다", "예화_적용": "작은 균열이라도 댐을 무너뜨릴 수 있다. 작아 보이는 죄도 하나님의 법을 위반하는 불법이다"},
    {"대지": "결론", "내용": "죄의 심각성을 깨달은 자만이 은혜의 위대함을 깨달을 수 있다. 죄를 가볍게 여기지 말고 하나님의 법 앞에 겸손히 서서 은혜를 구하자", "예화_적용": "병의 심각성을 아는 환자만이 의사의 처방을 진지하게 따른다. 죄의 심각성을 아는 성도만이 은혜를 진지하게 구한다"}
