    {"상황": "사회적으로 용납되는 죄에 무감각해진 성도", "성경원리": "죄의 기준은 사회가 아니라 하나님의 법이다. 세상이 용납해도 하나님의 법에 어긋나면 그것은 불법이다", "실제적용": "세상의 기준이 아니라 하나님의 기준으로 삶을 점검하도록 도우라. 말씀을 통해 하나님의 뜻을 분별하는 능력을 키워주라"}
