    {"교리": "성육신의 목적론", "설명": "그리스도의 성육신은 우리 죄를 없이 하려는 목적을 가졌다. 이것은 성육신이 인류 구속이라는 분명한 목적을 위한 것이었음을 보여준다. 나타남의 목적이 죄의 제거이다", "관련구절": "딤전 1:15, 요 1:29, 마 1:21, 갈 1:4"}
