    {"구분": "대속죄일의 속죄양", "내용": "대속죄일에 대제사장은 백성의 죄를 속죄양 위에 안수하여 놓고 광야로 보냈다(레 16:21-22). 이 양이 백성의 죄를 지고 가져갔다", "그리스도연결": "속죄양이 이스라엘의 죄를 지고 간 것은 그리스도가 우리의 죄를 없이 하시는 것의 예표이다. 그리스도는 우리의 죄를 완전히 들어 올려 제거하셨다"}
