    {"대지": "서론", "내용": "4절에서 죄의 심각성을 선언한 후 5절에서는 그 죄의 해결자를 소개한다. 문제 뒤에 반드시 해답이 따른다. 죄의 문제에 대한 해답은 그리스도이시다", "예화_적용": "암 진단 후에 가장 중요한 것은 치료법이다. 죄의 진단 후에 가장 중요한 것은 그 해결책인 그리스도이다"},
    {"대지": "1대지: 나타내신 바 되었다 (성육신의 사실)", "내용": "그리스도는 목적을 가지고 이 세상에 나타나셨다. 성육신은 우연이나 사건이 아니라 인류 구속을 위한 하나님의 계획된 행동이었다", "예화_적용": "소방관이 불길 속에 뛰어드는 것은 목적이 있기 때문이다. 그리스도가 이 세상에 오신 것도 분명한 목적이 있었다"},
    {"대지": "2대지: 우리 죄를 없이 하려고 (성육신의 목적)", "내용": "성육신의 목적은 죄의 제거이다. 들어 올려 가져간다는 뜻의 원어는 그리스도가 우리의 죄라는 무거운 짐을 자신이 지시고 완전히 제거하셨음을 보여준다", "예화_적용": "어린아이가 무거운 짐을 들지 못할 때 아버지가 대신 들어준다. 그리스도는 우리가 감당할 수 없는 죄의 짐을 들어 올려 제거해주셨다"},
    {"대지": "3대지: 그에게는 죄가 없느니라 (대속의 자격)", "내용": "그리스도의 무죄성은 대속의 필수 자격이다. 죄 있는 자는 다른 죄인의 대속물이 될 수 없다. 오직 죄 없으신 분만이 죄인의 죄를 없이 할 수 있다", "예화_적용": "빚이 있는 사람은 다른 사람의 보증인이 될 수 없다. 그러나 부자는 빚진 자의 빚을 대신 갚아줄 수 있다"},
    {"대지": "결론", "내용": "우리의 죄를 없이 하기 위해 죄 없으신 그리스도가 오셨다. 이 복음 앞에서 감사하며 죄에서 벗어나 깨끗한 삶을 살아가자", "예화_적용": "비싼 대가를 치르고 풀려난 포로는 다시 감옥에 들어가려 하지 않는다. 그리스도의 피값으로 죄에서 해방된 우리는 다시 죄의 종이 되지 말아야 한다"}
