    {"대지": "서론", "내용": "요한은 거듭남의 놀라운 결과를 선언한다. 하나님에게서 난 자 안에 하나님의 씨가 거하며 이 씨가 죄의 지배를 깨뜨린다. 거듭남은 본질적 변화이다", "예화_적용": "애벌레가 나비가 되면 더 이상 땅을 기어다니지 않는다. 본성이 바뀌었기 때문이다. 거듭남도 본성의 변화이다"},
    {"대지": "1대지: 하나님께로서 난 자 (거듭남의 사실)", "내용": "하나님에게서 났다는 것은 하나님의 생명으로 새롭게 태어난 것이다. 이것은 인간의 노력이 아니라 하나님의 능력으로 된 것이다. 완료 시제는 이 거듭남이 확정적 사건임을 보여준다", "예화_적용": "태어남은 되돌릴 수 없다. 하나님에게서 난 것도 되돌릴 수 없는 영원한 사건이다"},
    {"대지": "2대지: 하나님의 씨가 거함 (새 본성의 원리)", "내용": "하나님의 씨는 하나님의 생명과 본성의 원리이다. 이 씨가 성도 안에 거하며 새로운 본성으로 작용한다. 이 씨의 생명력이 죄의 힘을 이긴다", "예화_적용": "작은 씨앗이 바위를 뚫고 자라듯 하나님의 씨는 죄의 단단한 벽을 뚫고 자란다"},
    {"대지": "3대지: 범죄치 못하는 것 (새 본성의 능력)", "내용": "거듭난 본성은 죄를 삶의 패턴으로 삼을 수 없다. 이것은 완전무결이 아니라 방향의 변화이다. 새 본성은 죄를 향해 가지 않고 하나님을 향해 간다", "예화_적용": "나침반의 바늘이 항상 북쪽을 가리키듯 거듭난 자의 새 본성은 항상 하나님을 향한다. 바람에 흔들려도 결국 북쪽으로 돌아온다"},
    {"대지": "결론", "내용": "하나님의 씨가 우리 안에 있다. 이 씨의 능력을 신뢰하고 성령의 도우심으로 날마다 새 본성의 삶을 살아가자. 넘어져도 다시 일어나는 것이 하나님에게서 난 자의 특징이다", "예화_적용": "오뚝이는 넘어져도 다시 일어난다. 무게 중심이 아래에 있기 때문이다. 하나님의 씨가 우리의 무게 중심이 되면 넘어져도 다시 일어난다"}
