    {"새찬송가": "495", "통일찬송가": "369", "제목": "사랑하는 나의 아버지", "선정이유": "하나님 아버지의 사랑 안에서 형제를 사랑하는 삶을 노래한다"},
    {"새찬송가": "453", "통일찬송가": "338", "제목": "주님의 뜻을 이루소서", "선정이유": "시기와 미움을 버리고 주님의 뜻인 사랑을 행하겠다는 헌신을 표현한다"}
