    {"상황": "세상에서 인정받고 싶은 욕구와 신앙 사이에서 갈등하는 성도", "성경원리": "세상의 인정과 하나님의 인정을 동시에 추구할 수 없을 때가 있다. 하나님의 인정이 세상의 인정보다 더 가치 있다", "실제적용": "세상의 인정 욕구를 부정하지 말되 하나님의 인정의 가치를 깨닫게 하라. 영원한 것과 일시적인 것의 차이를 묵상하게 하라"}
