    {"대지": "서론", "내용": "요한은 16절에서 목숨을 버리는 위대한 사랑을 말한 후 17절에서 물질을 나누는 일상적 사랑으로 내려온다. 목숨을 버리겠다면서 돈을 나누지 않는 것은 모순이다. 사랑은 일상에서 검증된다", "예화_적용": "대학 입시에서 A를 받은 학생이 일상 시험에서 F를 받으면 무언가 잘못된 것이다. 위대한 사랑을 고백하면서 일상적 나눔에 실패하면 무언가 잘못된 것이다"},
    {"대지": "1대지: 이 세상 재물을 가지고 (가진 자의 책임)", "내용": "재물은 나누라고 주어진 것이다. 가진 것은 하나님이 맡기신 것이며 형제의 필요에 응답하는 데 쓰여야 한다", "예화_적용": "재물의 주인은 하나님이시고 우리는 청지기이다. 청지기는 주인의 뜻대로 재물을 사용해야 한다"},
    {"대지": "2대지: 궁핍함을 보고도 (보는 책임)", "내용": "형제의 궁핍을 보는 것에는 책임이 따른다. 본 것에 대해 응답해야 한다. 눈을 감는 것도 마음을 닫는 것의 한 형태이다", "예화_적용": "길에서 쓰러진 사람을 보고 지나가는 것은 레위인과 제사장의 모습이다. 멈추어 도와주는 것이 선한 사마리아인의 모습이다"},
    {"대지": "3대지: 마음을 막으면 (사랑의 흐름을 차단)", "내용": "마음을 막는 것은 의도적 행위이다. 하나님의 사랑이 흘러가는 통로를 차단하는 것이다. 이것은 하나님의 사랑이 그 안에 거하지 않는다는 증거이다", "예화_적용": "파이프가 막히면 물이 흐르지 않는다. 마음이 막히면 하나님의 사랑이 흐르지 않는다"},
    {"대지": "결론", "내용": "하나님의 사랑이 내 안에 거하고 있다면 그 사랑은 반드시 형제에게 흘러간다. 마음을 막지 말고 재물을 나누고 긍휼을 실천하자. 이것이 사랑의 일상적 증거이다", "예화_적용": "샘물이 마르지 않듯 하나님의 사랑으로 채워진 마음은 나눔이 마르지 않는다"}
