    {"원어": "ἀληθείᾳ (알레데이아)", "의미_문법": "진실함, 진리 - 명사 여성 단수 여격. 거짓 없는 참됨", "설교포인트": "진실함은 행함의 동기를 가리킨다. 겉으로 보여주기 위한 것이 아니라 진심에서 우러나오는 사랑이어야 한다"}
