    {"구분": "라합의 행동하는 믿음", "내용": "라합은 말로만 여호와를 고백한 것이 아니라 실제로 정탐꾼들을 숨겨주는 행동을 했다(수 2장). 행동이 믿음을 증명하였다", "그리스도연결": "라합의 행동하는 믿음은 행함과 진실함의 사랑의 모범이다. 그리스도의 사랑도 말씀뿐 아니라 십자가의 행동으로 증명되었다"}
