    {"원어": "ὄνομα (오노마)", "의미_문법": "이름 - 명사 중성 단수 여격. 그 인격과 본질 전체를 대표함", "설교포인트": "이름은 그 인격 전체를 대표한다. 예수 그리스도의 이름을 믿는다는 것은 그분의 인격과 사역 전체를 신뢰하는 것이다"},
    {"원어": "ἀγαπῶμεν (아가포멘)", "의미_문법": "사랑하자 - 동사 현재 능동태 가정법 1인칭 복수. 지속적으로 사랑함", "설교포인트": "현재 시제는 사랑의 지속성을 강조한다. 믿음은 결정적 행위이고 사랑은 지속적 실천이다. 믿음과 사랑이 함께 계명을 구성한다"}
