  "표8_상담적용": [
    {"상황": "믿음은 있지만 형제 사랑이 부족한 성도", "성경원리": "믿음과 사랑은 하나의 계명으로 분리될 수 없다. 그리스도를 믿으면서 형제를 사랑하지 않는 것은 계명의 절반만 지키는 것이다", "실제적용": "믿음이 사랑으로 열매 맺어야 함을 가르치라. 구체적인 형제 사랑의 실천 방법을 함께 찾도록 도우라. 작은 관심과 친절부터 시작하라"},
    {"상황": "사회적 봉사는 열심히 하지만 그리스도에 대한 믿음의 확신이 약한 성도", "성경원리": "사랑의 근원은 그리스도에 대한 믿음이다. 믿음 없는 사랑은 뿌리 없는 나무와 같다. 그리스도를 믿는 것이 사랑의 동기와 능력의 원천이다", "실제적용": "봉사의 동기가 어디에 있는지 점검하게 하라. 그리스도에 대한 인격적 믿음을 깊이 하도록 안내하라. 믿음이 사랑을 지속시키는 힘이 됨을 가르치라"}
  ],
  "표9_교차참조": [
    {"구절": "마 22:37-40", "연결점": "네 마음을 다하고 목숨을 다하고 뜻을 다하여 주 너의 하나님을 사랑하라 - 둘째도 그와 같으니 네 이웃을 네 몸과 같이 사랑하라", "구분": "신약"},
    {"구절": "요 6:29", "연결점": "예수께서 대답하여 가라사대 하나님의 보내신 자를 믿는 것이 하나님의 일이니라", "구분": "신약"},
    {"구절": "갈 5:6", "연결점": "그리스도 예수 안에서는 할례나 무할례가 효력이 없되 사랑으로써 역사하는 믿음뿐이니라", "구분": "신약"},
    {"구절": "롬 10:9", "연결점": "네가 만일 네 입으로 예수를 주로 시인하며 또 하나님께서 그를 죽은 자 가운데서 살리신 것을 네 마음에 믿으면 구원을 얻으리니", "구분": "신약"},
    {"구절": "신 6:4-5", "연결점": "이스라엘아 들으라 우리 하나님 여호와는 오직 하나인 여호와시니 너는 마음을 다하고 성품을 다하고 힘을 다하여 네 하나님 여호와를 사랑하라", "구분": "구약"},
    {"구절": "요 13:34", "연결점": "새 계명을 너희에게 주노니 서로 사랑하라 내가 너희를 사랑한 것같이 너희도 서로 사랑하라", "구분": "신약"}
  ]
