    {"구분": "에스겔의 새 영의 약속", "내용": "내가 새 영을 너희 속에 두고 새 마음을 너희에게 주되 너희 육신에서 굳은 마음을 제하고 부드러운 마음을 줄 것이며 내 신을 너희 속에 두어 너희로 내 율례를 행하게 하리라(겔 36:26-27)", "그리스도연결": "에스겔의 새 영의 약속이 오순절에 성취되었다. 성령이 우리 안에 거하시어 하나님의 계명을 행할 수 있게 하신다"}
