    {"새찬송가": "180", "통일찬송가": "180", "제목": "성령의 은사를", "선정이유": "성령의 역사와 그 안에 거하시는 하나님을 찬양한다"},
    {"새찬송가": "419", "통일찬송가": "313", "제목": "나의 생명 드리니", "선정이유": "주 안에 거하며 온전히 헌신하는 삶을 노래한다"}
