    {"구절": "요 14:23", "연결점": "사람이 나를 사랑하면 내 말을 지키리니 내 아버지께서 저를 사랑하실 것이요 우리가 저에게 와서 거처를 저와 함께 하리라", "구분": "신약"},
    {"구절": "롬 8:9-11", "연결점": "만일 너희 속에 하나님의 영이 거하시면 너희가 육신에 있지 아니하고 영에 있나니 누구든지 그리스도의 영이 없으면 그리스도의 사람이 아니라", "구분": "신약"},
    {"구절": "고전 6:19", "연결점": "너희 몸은 너희가 하나님께로부터 받은 바 너희 가운데 계신 성령의 전인 줄을 알지 못하느냐", "구분": "신약"},
    {"구절": "출 40:34-35", "연결점": "구름이 회막에 덮이고 여호와의 영광이 성막에 충만하매", "구분": "구약"},
    {"구절": "겔 36:26-27", "연결점": "또 새 영을 너희 속에 두고 - 내 신을 너희 속에 두어 너희로 내 율례를 행하게 하리라", "구분": "구약"},
    {"구절": "엡 1:13-14", "연결점": "너희도 그 안에서 진리의 말씀 곧 너희의 구원의 복음을 듣고 그 안에서 또한 믿어 약속의 성령으로 인치심을 받았으니", "구분": "신약"}
