    {"상황": "사랑받지 못했다는 상처로 사랑하기 어려운 성도", "성경원리": "참된 사랑의 근원은 인간이 아니라 하나님이시다. 인간에게 받지 못한 사랑을 하나님에게서 받을 수 있다. 하나님의 사랑이 모든 상처를 치유한다", "실제적용": "인간의 사랑의 한계를 인정하고 하나님의 무조건적 사랑을 경험하도록 도우라. 하나님의 사랑 안에서 치유를 받은 후에 타인을 사랑할 수 있음을 알려주라"}
