    {"새찬송가": "280", "통일찬송가": "329", "제목": "주 예수 내가 알기 전", "선정이유": "예수님을 알고 고백하는 신앙의 기쁨을 노래한다"},
    {"새찬송가": "488", "통일찬송가": "419", "제목": "예수를 나의 구주 삼고", "선정이유": "예수님을 구주로 고백하고 따르는 삶을 노래한다"}
