    {"항목": "초대교회의 재림 대망", "내용": "초대교회는 그리스도의 재림과 심판을 간절히 기다렸다. 요한은 이 기다림이 두려움이 아니라 담대함이어야 한다고 가르친다", "목회적활용": "재림과 심판에 대한 기대는 두려움이 아니라 소망이어야 한다. 사랑 안에서 온전한 자는 담대히 그 날을 기다릴 수 있다"}
