    {"교리": "그리스도와의 유사성", "설명": "주의 어떠하심과 같이 우리도 이 세상에서 그러하다는 것은 성화의 목표가 그리스도를 닮는 것임을 보여준다. 사랑 안에서 온전히 된 자는 그리스도의 성품을 반영한다", "관련구절": "롬 8:29, 고후 3:18, 엡 4:13, 골 3:10"}
