    {"구분": "다니엘의 사자 굴에서의 담대함", "내용": "다니엘은 사자 굴에 던져졌지만 두려워하지 않았다(단 6장). 하나님과의 관계가 분명한 자는 어떤 심판 앞에서도 담대하다", "그리스도연결": "다니엘의 담대함이 하나님과의 관계에서 나왔듯이 성도의 심판 날의 담대함도 사랑 안에 거하는 관계에서 나온다"}
