    {"원어": "ψεύστης (프슈스테스)", "의미_문법": "거짓말하는 자, 거짓말쟁이 - 명사 남성 단수 주격. 프세우도마이(속이다)에서 파생", "설교포인트": "요한은 형제를 미워하면서 하나님을 사랑한다는 자를 거짓말쟁이라고 단호하게 규정한다. 이것은 자기기만이다"},
    {"원어": "δύναται (뒤나타이)", "의미_문법": "~할 수 있다(뒤나마이)의 현재 중간태/수동태 직설법 3인칭 단수. 능력과 가능성의 부정", "설교포인트": "보이는 형제를 사랑하지 못하는 자가 보이지 않는 하나님을 사랑하는 것은 불가능하다. 할 수 없다는 단호한 선언이다"}
