    {"항목": "구약의 이웃 사랑 계명", "내용": "레위기 19장 18절의 네 이웃 사랑하기를 네 자신과 같이 하라는 계명은 구약의 핵심 계명이었다. 예수님은 이것을 첫째 계명(하나님 사랑)과 같은 둘째 계명으로 연결하셨다(마 22:39)", "목회적활용": "하나님 사랑과 이웃 사랑은 하나의 계명의 두 면이다. 분리할 수 없다"}
