    {"구분": "요셉의 형제들", "내용": "요셉의 형제들은 아버지 야곱의 축복 아래 있으면서도 형제 요셉을 미워하고 팔아넘겼다(창 37장). 가정의 사랑과 형제 미움이 공존한 비극이다", "그리스도연결": "요셉의 형제들이 결국 회개하고 화해했듯이 형제를 미워하는 자도 회개하여 사랑으로 돌아와야 한다"}
