    {"항목": "사랑의 이중 계명 전통", "내용": "유대 전통에서 하나님 사랑(신 6:5)과 이웃 사랑(레 19:18)은 율법의 두 기둥이었다. 예수님은 이 둘을 하나로 묶으셨고 요한은 이 전통을 계승한다", "목회적활용": "하나님 사랑과 형제 사랑은 하나의 계명의 두 면이다. 하나 없이 다른 하나는 성립하지 않는다"}
