    {"대지": "서론", "내용": "요한일서 4장의 마지막 절은 전체 장의 결론이며 핵심 요약이다. 하나님을 사랑하는 자는 형제도 사랑해야 한다. 이것이 주께 받은 계명이다. 단순하고 분명한 결론이다", "예화_적용": "좋은 설교는 한 문장으로 요약된다. 요한일서 4장의 요약은 하나님 사랑하면 형제도 사랑하라이다"},
    {"대지": "1대지: 주께 받은 계명 (권위)", "내용": "이 계명은 인간의 제안이 아니라 주님에게서 직접 받은 것이다. 신적 권위를 가진 명령이다. 선택 사항이 아니라 필수 사항이다. 계명을 주신 분의 권위가 계명의 무게를 결정한다", "예화_적용": "국가의 법률은 반드시 지켜야 한다. 하물며 하나님이 직접 주신 계명은 반드시 순종해야 한다"},
    {"대지": "2대지: 하나님을 사랑하는 자 (조건)", "내용": "하나님을 사랑하는 자라면 형제도 사랑해야 한다. 이것은 조건이자 당연한 결과이다. 하나님의 사랑을 받은 자는 그 사랑을 형제에게 나누는 것이 자연스럽다", "예화_적용": "밝은 방에 있으면 자연히 밝아지듯 하나님의 사랑 안에 있으면 자연히 형제를 사랑하게 된다"},
    {"대지": "3대지: 형제도 사랑하라 (실천)", "내용": "형제 사랑은 구체적 실천이다. 필요를 채우고 용서하며 격려하고 함께하는 것이다. 추상적 사랑이 아니라 일상의 사랑이다. 교회 안에서 이 사랑을 실천해야 한다", "예화_적용": "요리법을 아는 것과 실제로 요리하는 것은 다르다. 사랑의 계명을 아는 것과 실제로 사랑하는 것은 다르다. 실천이 관건이다"},
    {"대지": "결론", "내용": "요한일서 4장의 결론은 분명하다. 하나님을 사랑하는 자는 형제도 사랑해야 한다. 이것이 주님의 계명이다. 이 계명을 순종하며 사랑의 공동체를 이루자", "예화_적용": "오케스트라의 모든 악기가 하나의 선율을 연주할 때 아름다운 화음이 나듯 교회의 모든 성도가 사랑을 실천할 때 아름다운 공동체가 된다"}
